INSERT INTO community_posts(user_id,title,content,destination,category,style,likes,comments,created_at) SELECT 1,'A calm weekend in Kyoto','If you want a slower Japan experience, stay near Higashiyama and start sightseeing before 8 AM. The quiet streets are worth the early wake-up.','Kyoto','tip','Relaxed',28,6,'2026-08-20 09:15:00' WHERE NOT EXISTS (SELECT 1 FROM community_posts);
INSERT INTO community_posts(user_id,title,content,destination,category,style,likes,comments,created_at) SELECT 1,'Best street food finds','I kept the food budget low by exploring local markets and small neighbourhood stalls instead of tourist-heavy restaurants.','Osaka','food','Budget',42,11 WHERE (SELECT COUNT(*) FROM community_posts)=1;
INSERT INTO community_posts(user_id,title,content,destination,category,style,likes,comments,created_at) SELECT 1,'What I learned from my first solo trip','Leave some space in the itinerary. My favourite moments came from unplanned walks, local conversations and changing plans when the weather shifted.','Tokyo','experience','Adventure',35,8 WHERE (SELECT COUNT(*) FROM community_posts)=2;
INSERT INTO community_posts(user_id,title,content,destination,category,style,likes,comments,created_at) SELECT 1,'A simple way to save on transport','Compare day passes with individual fares before buying. For multi-city trips, check regional passes only after mapping your actual travel days.','Japan','budget','Balanced',51,14 WHERE (SELECT COUNT(*) FROM community_posts)=3;
INSERT INTO community_posts(user_id,title,content,destination,category,style,likes,comments,created_at) SELECT 1,'Small safety habit that helped me','Save your hotel address offline, keep a backup payment method separate, and share your daily plan with someone you trust.','Kyoto','safety','Balanced',24,5 WHERE (SELECT COUNT(*) FROM community_posts)=4;
